import sys
from collections import deque

def find_dag(n, edges):
    adj_list = [[] for _ in range(n)]
    in_degree = [0] * n
    undirected_edges = []

    for t, x, y in edges:
        if t == 1:
            adj_list[x-1].append(y-1)
            in_degree[y-1] += 1
        else:
            undirected_edges.append((x-1, y-1))

    queue = deque([i for i in range(n) if in_degree[i] == 0])
    topo_order = []

    while queue:
        node = queue.popleft()
        topo_order.append(node)
        for neighbor in adj_list[node]:
            in_degree[neighbor] -= 1
            if in_degree[neighbor] == 0:
                queue.append(neighbor)

    if len(topo_order) != n:
        return "NO", []

    directed_edges = []
    for x, y in edges:
        if x < y and (x-1, y-1) in undirected_edges:
            directed_edges.append((x, y))
        elif x > y and (y-1, x-1) in undirected_edges:
            directed_edges.append((y, x))
        elif x == y:
            pass
        else:
            directed_edges.append((x, y))

    for x, y in undirected_edges:
        if x not in topo_order or y not in topo_order:
            return "NO", []
        if topo_order.index(x) < topo_order.index(y):
            directed_edges.append((x+1, y+1))
        else:
            directed_edges.append((y+1, x+1))

    return "YES", directed_edges

def main():
    import sys
    input = sys.stdin.read().splitlines()
    ptr = 0
    t = int(input[ptr])
    ptr += 1
    results = []

    for _ in range(t):
        n, m = map(int, input[ptr].split())
        ptr += 1
        edges = [tuple(map(int, input[ptr + i].split())) for i in range(m)]
        ptr += m
        result, directed_edges = find_dag(n, edges)
        results.append(result)
        if result == "YES":
            for edge in directed_edges:
                results.append(f"{edge[0]} {edge[1]}")

    print("\n".join(results))

main()
